import fs from 'node:fs';import assert from 'node:assert/strict';
const pages=await(await fetch('http://127.0.0.1:9338/json/list')).json();const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);let serial=0;const pending=new Map(),errors=[];ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const c=pending.get(m.id);pending.delete(m.id);if(c)m.error?c.reject(Error(JSON.stringify(m.error))):c.resolve(m.result);}else if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);};const rpc=(method,params={})=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});const ev=async expression=>{const r=await rpc('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};let checks=0;const check=(name,v)=>{assert.ok(v,name);checks++;console.log('PASS',name);};const tick=()=>new Promise(r=>setTimeout(r,100));
try{await rpc('Runtime.enable');check('workbench ready',await ev('workbench.ready'));check('low frequency actions live in more menu',await ev('["wb-rename","wb-export","wb-process","wb-refresh-catalog"].every(id=>document.getElementById(id).closest("#wb-more-menu"))'));check('zero task count hidden',await ev('document.getElementById("wb-count").hidden'));
await ev('document.getElementById("btn-theme").click()');await tick();
for(const width of [1283,1024,800]){await rpc('Emulation.setDeviceMetricsOverride',{width,height:683,deviceScaleFactor:1,mobile:false});await tick();check(`single row at ${width}px`,await ev('(()=>{const a=[...document.querySelectorAll(".wb-actions>button")].map(e=>e.getBoundingClientRect());return a.every(r=>Math.abs(r.top-a[0].top)<1)&&a[0].left>document.querySelector(".head-left").getBoundingClientRect().right-1&&a.at(-1).right<innerWidth;})()'));}
await rpc('Emulation.clearDeviceMetricsOverride');await ev('document.getElementById("wb-more").click()');await tick();check('menu opens with updated expanded state',await ev('document.getElementById("wb-more-menu").matches(":popover-open")&&document.getElementById("wb-more").getAttribute("aria-expanded")==="true"'));check('menu stays in viewport',await ev('(()=>{const r=document.getElementById("wb-more-menu").getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.bottom<=innerHeight;})()'));
const clip=await ev('(()=>{const r=document.querySelector(".head-right").getBoundingClientRect();return {x:Math.max(0,r.left-35),y:Math.max(0,r.top-20),width:Math.min(innerWidth-r.left+35,r.width+50),height:Math.min(innerHeight-r.top+20,310),scale:1};})()');const shot=await rpc('Page.captureScreenshot',{format:'png',clip});fs.writeFileSync('tools/toolbar-redesign-20261101.png',Buffer.from(shot.data,'base64'));
await rpc('Input.dispatchKeyEvent',{type:'keyDown',key:'Escape',code:'Escape',windowsVirtualKeyCode:27});await rpc('Input.dispatchKeyEvent',{type:'keyUp',key:'Escape',code:'Escape',windowsVirtualKeyCode:27});await tick();check('Escape dismisses menu',await ev('!document.getElementById("wb-more-menu").matches(":popover-open")'));
await ev('document.getElementById("wb-more").focus()');await rpc('Input.dispatchKeyEvent',{type:'keyDown',key:'ArrowDown',code:'ArrowDown',windowsVirtualKeyCode:40});await tick();check('keyboard opens menu and focuses enabled item',await ev('document.activeElement.closest("#wb-more-menu")!==null'));await ev('document.getElementById("wb-process").click()');await tick();check('process toggle updates checkbox and closes menu',await ev('document.getElementById("wb-process").getAttribute("aria-checked")==="true"&&!document.getElementById("wb-more-menu").matches(":popover-open")'));
await ev('document.getElementById("wb-tasks").click()');check('tasks drawer still opens',await ev('!document.getElementById("wb-task-drawer").hidden'));await ev('document.getElementById("wb-drawer-close").click()');
check('input wording preserved',await ev('document.getElementById("prompt").placeholder.includes("Enter 发送，Shift+Enter 换行")'));check('no real model tasks started',await ev('workbench.state.tasks.length===0'));check('no runtime exceptions',errors.length===0);fs.writeFileSync('tools/toolbar-redesign-results-20261101.json',JSON.stringify({passed:true,checks,errors,type:'actual isolated Electron; no model tasks',date:new Date().toISOString()},null,2));console.log('CHECKS',checks);
}finally{await rpc('Emulation.clearDeviceMetricsOverride').catch(()=>{});ws.close();}
